<?php
$loanId = filter_var($_GET['id'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
if ($loanId === false) {
    echo '<div class="alert alert-danger">Identificador de empréstimo inválido.</div>';
    return;
}
$loanService = new LoanService();
$loan = $loanService->find((int) $user['id'], (int) $loanId);
$installments = $loanService->installments((int) $user['id'], (int) $loanId)['items'];
$s = (string) $loan['situacao'];
$badge = ['ativo' => 'primary', 'atrasado' => 'danger', 'quitado' => 'success', 'cancelado' => 'secondary'][$s] ?? 'secondary';
?>
<div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-4"><div><h2 class="mb-1">Empréstimo #<?= (int) $loan['id'] ?></h2><div class="text-muted"><?= FinPlanWeb::e($loan['cliente_nome']) ?> · <span class="badge text-bg-<?= $badge ?>"><?= FinPlanWeb::e(ucfirst($s)) ?></span></div></div><div class="d-flex gap-2"><a href="index.php?pagina=emprestimos" class="btn btn-outline-secondary">Voltar</a><?php if ($loan['status'] === 'ativo'): ?><a href="index.php?pagina=parcelas" class="btn btn-outline-primary">Ver parcelas</a><?php endif; ?></div></div>
<div class="row g-3 mb-4">
    <?php foreach ([['Valor principal', $loan['valor_principal']], ['Total do contrato', $loan['valor_total']], ['Total recebido', $loan['total_pago']], ['Saldo a receber', $loan['saldo_a_receber']]] as [$label, $value]): ?><div class="col-sm-6 col-xl-3"><div class="card dashboard-card h-100"><div class="dashboard-label"><?= FinPlanWeb::e($label) ?></div><div class="dashboard-value dashboard-money"><?= FinPlanWeb::money($value) ?></div></div></div><?php endforeach; ?>
</div>
<div class="card shadow-sm mb-4"><h5 class="mb-3">Dados do contrato</h5><div class="row g-3"><div class="col-md-3"><div class="detail-label">Taxa mensal</div><div class="detail-value"><?= number_format((float) $loan['taxa_juros_mensal'], 4, ',', '.') ?>%</div></div><div class="col-md-3"><div class="detail-label">Parcelas</div><div class="detail-value"><?= (int) $loan['qtd_parcelas'] ?></div></div><div class="col-md-3"><div class="detail-label">Sistema</div><div class="detail-value">Tabela Price</div></div><div class="col-md-3"><div class="detail-label">Data do empréstimo</div><div class="detail-value"><?= FinPlanWeb::date($loan['data_emprestimo']) ?></div></div><div class="col-md-3"><div class="detail-label">Primeiro vencimento</div><div class="detail-value"><?= FinPlanWeb::date($loan['primeiro_vencimento']) ?></div></div><div class="col-md-3"><div class="detail-label">Juros totais</div><div class="detail-value"><?= FinPlanWeb::money($loan['total_juros']) ?></div></div><div class="col-md-3"><div class="detail-label">Juros recebidos</div><div class="detail-value"><?= FinPlanWeb::money($loan['juros_recebidos']) ?></div></div><div class="col-md-3"><div class="detail-label">Saldo devedor (principal)</div><div class="detail-value"><?= FinPlanWeb::money($loan['saldo_devedor']) ?></div></div><div class="col-12"><div class="detail-label">Observações</div><div class="detail-value"><?= FinPlanWeb::e($loan['observacoes'] ?: '—') ?></div></div></div>
    <?php if ($loan['status'] === 'ativo' && (float) $loan['total_pago'] === 0.0): ?><div class="border-top mt-3 pt-3"><form method="POST" action="index.php" onsubmit="return confirm('Deseja cancelar este contrato? O contrato e as parcelas serão preservados.');"><input type="hidden" name="_csrf" value="<?= FinPlanWeb::e(FinPlanWeb::csrfToken()) ?>"><input type="hidden" name="_action" value="loan_cancel"><input type="hidden" name="id" value="<?= (int) $loan['id'] ?>"><button class="btn btn-outline-danger btn-sm" type="submit">Cancelar empréstimo</button></form></div><?php endif; ?>
</div>
<div class="card shadow-sm"><div class="d-flex justify-content-between align-items-center mb-3"><div><h5 class="mb-1">Cronograma de parcelas</h5><p class="text-muted small mb-0">Juros, amortização, recebimentos e saldo individual.</p></div></div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Nº</th><th>Vencimento</th><th>Valor</th><th>Juros</th><th>Amortização</th><th>Pago</th><th>Saldo</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($installments as $item): ?>
    <?php $status = (string) $item['status']; $label = ['paga' => 'Paga', 'parcial' => 'Parcial', 'atrasada' => 'Atrasada', 'pendente' => 'Pendente'][$status] ?? $status; $statusColor = ['paga' => 'success', 'parcial' => 'warning', 'atrasada' => 'danger', 'pendente' => 'secondary'][$status] ?? 'secondary'; ?>
    <tr><td><?= (int) $item['numero'] ?></td><td><?= FinPlanWeb::date($item['vencimento']) ?></td><td><?= FinPlanWeb::money($item['valor']) ?></td><td><?= FinPlanWeb::money($item['valor_juros']) ?></td><td><?= FinPlanWeb::money($item['valor_amortizacao']) ?></td><td><?= FinPlanWeb::money($item['valor_pago']) ?></td><td><?= FinPlanWeb::money($item['saldo']) ?></td><td><span class="badge text-bg-<?= $statusColor ?>"><?= FinPlanWeb::e($label) ?></span></td><td class="text-end"><?php if ((float) $item['saldo'] > 0 && $loan['status'] === 'ativo'): ?><a href="index.php?pagina=receber_parcela&id=<?= (int) $item['id'] ?>" class="btn btn-success btn-sm">Receber</a><?php else: ?><span class="text-muted small">—</span><?php endif; ?></td></tr>
<?php endforeach; ?>
</tbody></table></div></div>
